// BEGIN: polyval_p

/**
* Evaluates a polynomial.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the polynomial
* @return     evaluated polynomial
*/
static float polyval_p( const float x ) {
	return -0.333332819422f + (x * (0.133314422036f + (x * (-0.0537397155531f + (x * (0.0206390887954f + (x * -0.00570498872745f)))))));
}

// END: polyval_p

/* End auto-generated functions. */

/**
* Computes the hyperbolic tangent of a single-precision floating-point number.
*
* ## Method
*
* For |x| < 0.625, we use a polynomial approximation of the form
*
* ```tex
* x + x^3 \mathrm{P}(x)
* ```
*
* Otherwise,
*
* ```tex
* \begin{align*}
* \operatorname{tanhf}(x) &= \frac{\operatorname{sinhf}(x)}{\operatorname{coshf}(x)} \\
* &= 1 - \frac{2}{e^{2x} + 1}
* \end{align*}
* ```
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_tanhf( 0.0f );
* // returns 0.0f
*/
float stdlib_base_tanhf( const float x ) {
	float s;
	float z;

	z = stdlib_base_absf( x );
	if ( z > 0.5f * STDLIB_CONSTANT_FLOAT32_MAX_LN ) {
		return ( x < 0.0f ) ? -1.0f : 1.0f;
	}
	if ( z >= 0.625f ) {
		s = stdlib_base_expf( 2.0f * z );
		z = 1.0f - ( 2.0f / ( s + 1.0f ) );
		if ( x < 0.0f ) {
			z = -z;
		}
	} else {
		if ( x == 0.0f ) {
			return x; // preserves signed zero
		}
		s = x * x;
		z = x + ( x * s * polyval_p( s ) );
	}
	return z;
}
